import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid webpage_url provided.")

    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
        parsed_html = html.fromstring(response.content)
        table = parsed_html.xpath('//table')[0]
    except requests.RequestException as e:
        raise requests.RequestException(f"Error accessing the URL: {e}")
    except IndexError:
        return 0

    headers = [header.text_content().strip() for header in table.xpath('.//th')]
    rows = []
    for row in table.xpath('.//tr'):
        cols = [col.text_content().strip() for col in row.xpath('.//td')]
        if cols:
            rows.append(cols)

    if not rows:
        return 0

    df = pd.DataFrame(rows, columns=headers if headers else None)

    try:
        connection = sqlite3.connect(database_name)
        with connection:
            df.to_sql('my_table', connection, if_exists='replace', index=False)
        return len(df)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    finally:
        if connection:
            connection.close()

