import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not isinstance(username, str) or not username:
        raise ValueError("Username must be a non-empty string.")

    try:
        response = requests.get(f"{URL}{username}", timeout=10)
        response.raise_for_status()
        user_data = response.json()
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}") from e

    def normalize_to_ascii(data):
        if isinstance(data, str):
            return unicodedata.normalize('NFKD', data).encode('ascii', 'ignore').decode('ascii')
        if isinstance(data, dict):
            return {k: normalize_to_ascii(v) for k, v in data.items()}
        if isinstance(data, list):
            return [normalize_to_ascii(item) for item in data]
        return data

    normalized_data = normalize_to_ascii(user_data)
    return normalized_data

